import{_ as e,o as r,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-09-16 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-09-16 :: Ceph Orchestration Meeting","date":"2019-09-16T00:00:00.000Z","updated":"2019-09-21T00:00:00.000Z","tags":["Ceph","Orchestrator","Rook","Distributed Storage","Meeting Summary"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-09-16_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-09-16_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-09-16_-_-_Ceph_Orchestration_Meeting.md"};function s(a,t,n,p,_,g){return r(),o("div",null,[...t[0]||(t[0]=[i("<p>会议纪要</p><p><strong>会议时间</strong>： 2019年9月某日</p><p><strong>参会人员</strong>： 会议记录者，Jonathan，DePaul，Percept，Travie，Adam Freeman等</p><p><strong>会议主题</strong>： 讨论Ceph项目的进展、问题及后续行动计划。</p><p><strong>关键细节</strong>：</p><ul><li><strong>Estate Orchestrator</strong>： Jonathan提到已将Estate Orchestrator的更改推送到分支，以便继续工作。他还提到了PR 3026，该PR使得completions可组合，这对于桌面和仪表板非常重要。</li><li><strong>Nautilus模块阻塞</strong>： 由于存在tracker issue 41737，Nautilus模块遇到了阻塞。该问题与两个端口有关，需要在master分支中修复。</li><li><strong>Rook 1.0</strong>： Rook 1.0已发布，目前看起来一切顺利。计划在本周进行补丁发布。</li><li><strong>Orchestrator问题</strong>： 讨论了关于polls的持续时间和reclaim策略的问题。决定更改默认策略以保留规则，并考虑在self中启用secure pull deletion标志。</li><li><strong>Rook CI</strong>： 讨论了Rook CI的未来。短期内，将更新旧的Jenkins实例。长期目标是实现自动化，类似于F CIA。会议决定将讨论移至上游，并与Greg和Adam Freeman一起讨论。</li></ul><p><strong>决定事项</strong>：</p><ul><li>将修复Nautilus模块的tracker issue 41737。</li><li>计划进行Rook 1.0的补丁发布。</li><li>更改默认策略以保留规则，并考虑在self中启用secure pull deletion标志。</li><li>将Rook CI讨论移至上游，并与Greg和Adam Freeman一起讨论。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Jonathan将继续工作在Estate Orchestrator上。</li><li>讨论修复Nautilus模块的tracker issue 41737。</li><li>计划进行Rook 1.0的补丁发布。</li><li>讨论并实施新的reclaim策略。</li><li>讨论并实施Rook CI的自动化。</li><li>将讨论移至上游，并与Greg和Adam Freeman一起讨论。</li></ul><p><strong>关键词</strong>：</p><ul><li>Estate Orchestrator</li><li>PR 3026</li><li>Nautilus</li><li>Rook 1.0</li><li>Orchestrator</li><li>polls</li><li>reclaim策略</li><li>Rook CI</li></ul>",12)])])}const h=e(l,[["render",s]]);export{u as __pageData,h as default};
